-- Adds PDF upload support (license/certification documents) to Providers.
-- Paste into Supabase SQL Editor and Run once.

alter table providers add column if not exists document_path text;
alter table providers add column if not exists document_name text;

-- Private storage bucket for provider PDFs (accessed only via short-lived
-- signed URLs generated by the app, never a public link).
insert into storage.buckets (id, name, public)
values ('provider-documents', 'provider-documents', false)
on conflict (id) do nothing;

drop policy if exists "authenticated manage provider documents" on storage.objects;
create policy "authenticated manage provider documents" on storage.objects
  for all using (bucket_id = 'provider-documents' and auth.role() = 'authenticated')
  with check (bucket_id = 'provider-documents' and auth.role() = 'authenticated');
